import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CQdiwDJy.js";const g=JSON.parse('{"title":"安全模型","description":"","frontmatter":{},"headers":[],"relativePath":"reference/safety.md","filePath":"reference/safety.md","lastUpdated":1788601681000}'),n={name:"reference/safety.md"};function i(l,e,s,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="安全模型" tabindex="-1">安全模型 <a class="header-anchor" href="#安全模型" aria-label="Permalink to &quot;安全模型&quot;">​</a></h1><p>Tau 的安全设计围绕一句话：<strong>AI 提议，规则审查，人来拍板。</strong> 全部机制都是确定性代码，没有&quot;AI 觉得没问题&quot;这种环节。</p><h2 id="三道门" tabindex="-1">三道门 <a class="header-anchor" href="#三道门" aria-label="Permalink to &quot;三道门&quot;">​</a></h2><ol><li><strong>计划校验</strong>——provider 输出必须是严格 JSON（zod schema，<code>additionalProperties: false</code>），宽松输出（含代码围栏、多余字段）直接拒绝。</li><li><strong>确定性审查</strong>——<code>reviewPlan()</code> 按规则给计划定级：allow / review / deny，附逐条 issue。审查者独立复核每个写路径，与工具自身的检查形成纵深防御。</li><li><strong>执行确认</strong>——deny 不可运行；high-risk 需要显式确认（CLI 交互确认、WebUI 卡片级勾选）；medium 写操作默认干跑，<code>execute: true</code> 才生效；agent 模式下 medium+ 轮次内联暂停等待批准，<strong>永远没有一次性预授权</strong>。</li></ol><h2 id="执行通道唯一" tabindex="-1">执行通道唯一 <a class="header-anchor" href="#执行通道唯一" aria-label="Permalink to &quot;执行通道唯一&quot;">​</a></h2><p><code>runPlan()</code> 是唯一执行通道，内部还会<strong>再次</strong>审查。任何界面（CLI/TUI/WebUI）、任何模式（ask/goal）、任何 provider，最终都汇到这里。不存在&quot;provider 直接跑命令&quot;的路径。</p><h2 id="具体的硬边界" tabindex="-1">具体的硬边界 <a class="header-anchor" href="#具体的硬边界" aria-label="Permalink to &quot;具体的硬边界&quot;">​</a></h2><ul><li><strong>没有 delete 工具</strong>：第一方工具族刻意不提供删除原语。</li><li><strong>工作区围栏</strong>：<code>file.write</code> 拒绝工作区外路径与系统位置（<code>/etc</code>、<code>/usr</code> 等），二进制目标与 &gt;2MB 内容拒绝。</li><li><strong>插件工具一律 medium</strong>：外部 MCP 工具不可审查内部实现，风险等级不因插件声明而降低。</li><li><strong>shell 步骤可中止</strong>：中止会杀掉整个进程组，不会留下孤儿进程。</li><li><strong>AI 永不自我评分</strong>：反思产生的下一轮计划同样要过确定性审查；反思只是提议，审查才是门。</li></ul><h2 id="流式不削弱安全-v0-5-0" tabindex="-1">流式不削弱安全（v0.5.0） <a class="header-anchor" href="#流式不削弱安全-v0-5-0" aria-label="Permalink to &quot;流式不削弱安全（v0.5.0）&quot;">​</a></h2><p>流式规划只改变文本&quot;何时到达&quot;，不改变&quot;如何被处理&quot;：流式组装出的计划仍走同一个 <code>validatePlanResponse()</code> 与 <code>reviewPlan()</code>；拒绝发生在流开始之前（纯 JSON 错误），不存在&quot;流式绕过审查&quot;的形态。</p><h2 id="可观测性" tabindex="-1">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h2><p>每次请求一行结构化日志（含 AI token 成本），WebUI 设置面板只展示脱敏配置——API key 永不明文出现在日志或浏览器。</p>',12)])])}const p=o(n,[["render",i]]);export{g as __pageData,p as default};
